function formatTime(t){if(!Number.isFinite(t))return '—';const m=Math.floor(t/60),s=(t%60).toFixed(2).padStart(5,'0');return m+':'+s;}
function formatDistance(metres){const imperial=settings().units==='mph';return(metres/(imperial?1609.344:1000)).toFixed(2)+(imperial?' mi':' km');}
function formatShortDistance(metres,remaining=false){const imperial=settings().units==='mph',value=metres/(imperial?0.3048:1);return(remaining?Math.max(1,Math.ceil(value)):Math.round(value))+(imperial?' ft':' m');}
