// This display tracks a driving streak; payments stay banked independently.
function clearCreditStreak(){creditStreak.total=0;creditStreak.lastProgress=0;creditStreak.lastDistance=sim?.eligibleDistance||0;for(const burst of creditStreak.bursts)burst.element.remove();creditStreak.bursts=[];creditTotal.textContent='';creditTotal.hidden=true;creditMeter.hidden=true;}
function addCreditStreak(amount){creditStreak.total+=amount;creditStreak.lastProgress=sim.time;creditStreak.lastDistance=sim.eligibleDistance;creditStreak.popAt=sim.time;creditTotal.textContent='+'+creditStreak.total.toLocaleString()+' CR';creditTotal.hidden=false;creditMeter.hidden=false;}
function breakCreditStreak(){if(!creditStreak.total)return;const element=document.createElement('div');element.className='drive-credit-burst';const characters=Array.from(creditTotal.textContent);const shards=characters.map((character,index)=>{const span=document.createElement('span');span.className='drive-credit-shard';span.textContent=character;element.append(span);return{span,vx:(index-(characters.length-1)/2)*45+(index%2?10:-10),vy:-55-index*14,spin:(index%2?1:-1)*.65};});creditMeter.append(element);creditStreak.bursts.push({element,shards,bornAt:sim.time});while(creditStreak.bursts.length>3)creditStreak.bursts.shift().element.remove();creditStreak.total=0;creditTotal.hidden=true;}
function updateCreditStreak(){const now=sim.time,distance=sim.eligibleDistance;if(distance>creditStreak.lastDistance+1e-6)creditStreak.lastProgress=now;creditStreak.lastDistance=distance;if(creditStreak.total&&now-creditStreak.lastProgress>=1.5)breakCreditStreak();creditStreak.bursts=creditStreak.bursts.filter(burst=>{if(now-burst.bornAt<1.15)return true;burst.element.remove();return false;});creditMeter.hidden=!creditStreak.total&&!creditStreak.bursts.length;}
function renderCreditStreak(){if(creditMeter.hidden)return;const now=sim.time,reduced=settings().reducedMotion||motionPreference.matches;creditTotal.style.transform=reduced?'none':'scale('+(1+.18*Math.max(0,1-(now-creditStreak.popAt)/.16))+')';for(const burst of creditStreak.bursts){const age=Math.max(0,now-burst.bornAt);burst.element.style.opacity=Math.max(0,1-age/1.15);for(const shard of burst.shards)shard.span.style.transform=reduced?'none':`translate(${shard.vx*age}px,${shard.vy*age+160*age*age}px) rotate(${shard.spin*age}rad)`;}}
