function garageStats(id,preview=null){
 const current=Core.getPerformanceStats(configFor(id)),shown=preview?Core.getPerformanceStats(preview):current,imperial=settings().units==='mph',factor=imperial?2.236936:3.6;
 const definitions=[['topSpeed','Top speed',imperial?'mph':'km/h',factor,0],['acceleration','Acceleration','m/s²',1,1],['traction','Traction','m/s²',1,1],['steering','Steering response','s⁻¹',1,2],['braking','Braking','m/s²',1,1]];
 if(!garageStatLimits){garageStatLimits={};for(const carId of Object.keys(Core.CARS)){const equipped=Object.fromEntries(Core.PART_CATEGORIES.map(k=>[k,Core.PARTS[k].at(-1).id])),config=Core.getConfig({selected:carId,customization:{[carId]:{equipped}}}),stats=Core.getPerformanceStats(config);for(const [key]of definitions)garageStatLimits[key]=Math.max(garageStatLimits[key]||0,stats[key]);}}
 return `<div class="drive-garage-stats" aria-label="Vehicle performance. White equipped, blue gain, red loss.">${definitions.map(([key,label,unit,mult,digits])=>{const a=current[key],b=shown[key],delta=b-a,base=Math.min(100,a/garageStatLimits[key]*100),value=Math.min(100,b/garageStatLimits[key]*100),change=Math.abs(delta)>1e-6?(delta>0?'gain':'loss'):'same',formatted=(b*mult).toFixed(digits)+' '+unit,difference=change==='same'?'':(delta>0?'+':'')+(delta*mult).toFixed(digits)+' '+unit;return `<div class="drive-performance-row" data-stat="${key}" data-current="${a}" data-preview="${b}" data-change="${change}"><div class="drive-performance-label"><small>${label}</small><strong>${formatted}${difference?`<em class="${change}">${difference}</em>`:''}</strong></div><div class="drive-stat-meter ${change}" role="meter" aria-label="${label}: equipped ${(a*mult).toFixed(digits)} ${unit}${change==='same'?'':', preview '+formatted}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${value.toFixed(2)}"><i class="drive-stat-reference" style="width:${base}%"></i><i class="drive-stat-fill" style="width:${change==='gain'?base:value}%"></i>${change==='gain'?`<i class="drive-stat-gain" style="left:${base}%;width:${value-base}%"></i>`:change==='loss'?`<i class="drive-stat-loss" style="left:${value}%;width:${base-value}%"></i>`:''}</div></div>`;}).join('')}</div>`;
}
function garagePartDetail(part,owned){const config=configFor(garageCar),selected=config.equipped[garageCategory],purchased=save.customization[garageCar]?.ownedParts[garageCategory]?.includes(part.id),equipped=selected===part.id;return `<div class="drive-part-detail"><h3>${escapeText(part.name)}</h3><p>${escapeText(part.description)}</p><p class="drive-part-effects">${partEffects(part)}</p><button class="primary" data-action="equipPart" ${!owned||equipped?'disabled':''}>${equipped?'Equipped':purchased?'Equip part':part.price.toLocaleString()+' CR · Buy & equip'}</button><button class="quiet drive-factory" data-action="factoryPart" ${!owned||!selected?'disabled':''}>${garageCategory==='spoilers'?'Remove spoiler':'Restore factory / retained upgrades'}</button></div>`;}
function garagePartsHTML(owned){
 const config=configFor(garageCar),category=garageCategory,list=Core.PARTS[category],selected=config.equipped[category],part=list.find(p=>p.id===garageOption)||list.find(p=>p.id===selected)||list[0];garageOption=part.id;
 return `<div class="drive-part-categories" aria-label="Part categories">${Core.PART_CATEGORIES.map(key=>`<button data-action="partCategory" data-category="${key}" class="${key===category?'active':''}" aria-pressed="${key===category}">${categoryLabels[key]}</button>`).join('')}</div><div class="drive-equipped-line"><span>EQUIPPED</span><strong>${escapeText(config.parts[category]?.name||'Factory / retained upgrades')}</strong></div><label class="drive-option-label" for="drivePartOption">Choose from 10 ${categoryLabels[category].toLowerCase()}</label><select id="drivePartOption" aria-label="${categoryLabels[category]} option">${list.map((p,i)=>`<option value="${p.id}" ${p.id===part.id?'selected':''}>${String(i+1).padStart(2,'0')} · ${escapeText(p.name)}${selected===p.id?' · EQUIPPED':save.customization[garageCar]?.ownedParts[category]?.includes(p.id)?' · OWNED':' · '+p.price.toLocaleString()+' CR'}</option>`).join('')}</select><div class="drive-part-choices" aria-label="Preview ${categoryLabels[category].toLowerCase()}">${list.map(p=>`<button type="button" data-action="previewPart" data-preview-part="${p.id}" aria-pressed="${garagePreviewOption===p.id}" class="${garagePreviewOption===p.id?'active':''}"><span>${escapeText(p.name)}</span><small>${selected===p.id?'EQUIPPED':save.customization[garageCar]?.ownedParts[category]?.includes(p.id)?'OWNED':p.price.toLocaleString()+' CR'}</small></button>`).join('')}</div>${garagePartDetail(part,owned)}<p class="drive-part-note">Hover, focus or tap a part to preview. Blue adds performance; red shows a loss compared with your equipped setup. Buy or equip to keep the change.</p>`;
}
function refreshGaragePreview(){
 if(!garageScene||state!=='garage')return;const config=garagePreviewConfig(),key=config.key+JSON.stringify(config.paint);if(key!==garagePreviewKey){garageSim.config=config;garageScene.setCar(config,config.paintColor);garagePreviewKey=key;}
 garageScene.playerConfig=config;garageScene.setSmokePreview(garageTab==='smoke'?(garageSmokeOption||config.smokeColor):null);
 $('.drive-garage-stats').outerHTML=garageStats(garageCar,garageTab==='parts'&&garagePreviewOption?config:null);const caption=$('#drivePreviewCaption');if(caption)caption.textContent=garageTab==='smoke'?'Smoke preview · '+(Core.SMOKE_COLORS.find(c=>c.id===garageSmokeOption)?.name||'Factory white'):garageTab==='parts'&&garagePreviewOption?'Part preview · not equipped':'Equipped performance';
}
function previewGaragePart(id){if(state!=='garage'||garageTab!=='parts'||!Core.PARTS[garageCategory].some(p=>p.id===id)||garagePreviewOption===id)return;finishGarageGesture();garageOption=garagePreviewOption=id;$('#drivePartOption').value=id;for(const button of root.querySelectorAll('[data-preview-part]')){button.classList.toggle('active',button.dataset.previewPart===id);button.setAttribute('aria-pressed',String(button.dataset.previewPart===id));}$('.drive-part-detail').outerHTML=garagePartDetail(Core.PARTS[garageCategory].find(p=>p.id===id),save.owned.includes(garageCar));refreshGaragePreview();}
function garageSmokeHTML(owned){const equipped=configFor(garageCar).smokeColor,item=Core.SMOKE_COLORS.find(c=>c.id===garageSmokeOption)||Core.SMOKE_COLORS.find(c=>c.id===equipped)||Core.SMOKE_COLORS[0];garageSmokeOption=item.id;return `<p class="drive-paint-help">Hover, focus or tap a color to see a frozen drift behind the rear wheels. Colors are unlocked for every owned car.</p><div class="drive-smoke-choices">${Core.SMOKE_COLORS.map(c=>`<button data-action="previewSmoke" data-preview-smoke="${c.id}" class="${c.id===item.id?'active':''}" aria-pressed="${c.id===item.id}"><i style="--smoke-color:${c.color}" class="${c.id}"></i><span>${escapeText(c.name)}</span><small>${equipped===c.id?'EQUIPPED':save.ownedSmoke.includes(c.id)?'OWNED':c.price.toLocaleString()+' CR'}</small></button>`).join('')}</div><div class="drive-smoke-detail"><h3>${escapeText(item.name)}</h3><p>${item.id==='galaxy'?'Purple, blue and pink clouds with little stars and ringed planets.':item.id==='gold'?'Warm golden clouds and bright star-shaped sparkles.':'Colored tire smoke follows your actual rear-wheel drift contacts.'}</p><button class="primary" data-action="equipSmoke" ${!owned||equipped===item.id?'disabled':''}>${equipped===item.id?'Equipped':save.ownedSmoke.includes(item.id)?'Equip smoke':item.price.toLocaleString()+' CR · Buy & equip'}</button></div>`;}
function previewGarageSmoke(id){if(state!=='garage'||garageTab!=='smoke'||!Core.SMOKE_COLORS.some(c=>c.id===id)||garageSmokeOption===id)return;garageSmokeOption=id;refreshGarageTools();}
function previewGarageCar(id){if(state!=='garage'||garageCar===id||!Core.CARS[id])return;const scroll=$('.drive-car-choices')?.scrollLeft||0,focused=document.activeElement?.dataset.previewCar;garage(id);$('.drive-car-choices').scrollLeft=scroll;if(focused===id)root.querySelector(`[data-preview-car="${id}"]`)?.focus({preventScroll:true});}

function partEffects(part){const labels={maxSpeed:'speed',speed:'speed',accel:'acceleration',acceleration:'acceleration',grip:'traction',traction:'traction',steering:'steering',brake:'braking',braking:'braking'};return Object.entries(part.modifiers||{}).filter(([key,value])=>labels[key]&&typeof value==='number').map(([key,value])=>'+'+((value>=1?value-1:value)*100).toFixed(1).replace(/\.0$/,'')+'% '+labels[key]).join(' · ');}
function garagePaintHTML(owned){const paint=configFor(garageCar).paint;return `<div class="drive-paint-mode"><button data-action="paintTool" data-tool="inspect" class="${garageTool==='inspect'?'active':''}" aria-pressed="${garageTool==='inspect'}">Inspect / rotate</button><button data-action="paintTool" data-tool="paint" class="${garageTool==='paint'?'active':''}" aria-pressed="${garageTool==='paint'}" ${owned?'':'disabled'}>Paint on body</button></div><p class="drive-paint-help">Switch to Paint, then draw on the visible body. Use Inspect or the arrow buttons to reach the other sides and roof.</p><label class="drive-paint-field">Brush color <input id="driveBrushColor" type="color" aria-label="Brush color" value="${brushColor}" ${owned?'':'disabled'}></label><label class="drive-paint-field">Brush size <input id="driveBrushSize" type="range" aria-label="Brush size" min=".005" max=".08" step=".005" value="${brushSize}" ${owned?'':'disabled'}><output>${Math.round(brushSize*1000)}</output></label><div class="drive-row drive-paint-actions"><button data-action="undoPaint" ${!owned||!paint.strokes.length?'disabled':''}>Undo stroke</button><button data-action="clearPaint" ${!owned||!paint.strokes.length?'disabled':''}>Clear markings</button></div><div class="drive-body-color"><span>Whole-body base color</span><div class="drive-paints">${Core.PAINTS.map(p=>`<button class="${paint.baseColor===p.color?'active':''}" style="background:${p.color}" aria-label="${p.name} paint" title="${p.name}" data-action="paint" data-paint="${p.id}" ${owned?'':'disabled'}></button>`).join('')}<input id="driveBaseColor" type="color" aria-label="Custom body color" value="${paint.baseColor}" ${owned?'':'disabled'}></div></div><p class="drive-part-note">Glass, lights, tires and trim stay separate. Markings travel with this car into every driving view.</p>`;}
function refreshGarageTools(){if(state!=='garage')return;garageCanvas.dataset.painting=String(garageTool==='paint'&&save.owned.includes(garageCar));$('#driveGarageTools').innerHTML=garageTab==='paint'?garagePaintHTML(save.owned.includes(garageCar)):garageTab==='smoke'?garageSmokeHTML(save.owned.includes(garageCar)):garagePartsHTML(save.owned.includes(garageCar));refreshGaragePreview();}
function returnFromGarage(){
 finishGarageGesture();writeSave();if(garageBack==='paused'&&sim){if(!sim.applyGarageConfig(configFor())){save.selected=garageEntrySelection;writeSave();toast('There is no clear space for this vehicle. Your previous car stays selected.');return;}applyAdmin();scene.setCar(configFor(),configFor().paintColor||colorFor(save.selected));configKey=sim.config.key;state=pausedState;disposeGarage();pause();}else{disposeGarage();menu();}
}
function finishGarageGesture(){if(!garageGesture&&!garagePaintDraft.length)return;const pointer=garageGesture?.pointer;garageGesture=null;if(garagePaintDraft.length&&saving){const result=Core.addPaintStroke(save,garagePaintDraft,garageCar);if(result?.ok===false)toast(result.reason||'Painting could not be saved.');garagePaintDraft=[];garageScene?.setPaint(configFor(garageCar).paint);writeSave();refreshGarageTools();}else garagePaintDraft=[];if(pointer!==undefined&&garageCanvas?.hasPointerCapture(pointer))garageCanvas.releasePointerCapture(pointer);}
function paintGaragePoint(x,y){const hit=garageScene.pickPaint(x,y);if(!hit)return;const previous=garagePaintDraft.at(-1);if(previous&&previous.surface===hit.surface&&Math.hypot(previous.u-hit.u,previous.v-hit.v)<brushSize*.3)return;const base=configFor(garageCar).paint;if(base.strokes.length+garagePaintDraft.length>=1400){if(!garageGesture.full){toast('Paint is full. Undo a stroke or clear markings to make room.');garageGesture.full=true;}return;}garagePaintDraft.push({...hit,r:brushSize,color:brushColor,stroke:garageGesture.stroke});garageScene.setPaint({...base,strokes:[...base.strokes,...garagePaintDraft]});}
function bindGarageCanvas(){
 garageCanvas.addEventListener('contextmenu',e=>e.preventDefault());
 garageCanvas.addEventListener('pointerdown',e=>{if(state!=='garage'||garageGesture||e.button!==0)return;e.preventDefault();clearInput();const painting=garageTool==='paint'&&save.owned.includes(garageCar);garageGesture={pointer:e.pointerId,x:e.clientX,y:e.clientY,painting,stroke:Math.max(0,...configFor(garageCar).paint.strokes.map(s=>s.stroke||0))+1};garageCanvas.setPointerCapture(e.pointerId);if(painting)paintGaragePoint(e.clientX,e.clientY);});
 garageCanvas.addEventListener('pointermove',e=>{if(!garageGesture||garageGesture.pointer!==e.pointerId)return;e.preventDefault();const g=garageGesture,dx=e.clientX-g.x,dy=e.clientY-g.y;if(g.painting){const steps=Math.min(60,Math.max(1,Math.ceil(Math.hypot(dx,dy)/3)));for(let i=1;i<=steps;i++)paintGaragePoint(g.x+dx*i/steps,g.y+dy*i/steps);}else{garageScene.inspection.yaw+=dx*.012;garageScene.inspection.elevation=Math.max(.8,Math.min(6,garageScene.inspection.elevation+dy*.012));}g.x=e.clientX;g.y=e.clientY;});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])garageCanvas.addEventListener(event,e=>{if(garageGesture?.pointer===e.pointerId)finishGarageGesture();});
 garageCanvas.addEventListener('wheel',e=>{if(state!=='garage')return;e.preventDefault();garageScene.inspection.distance=Math.max(3.7,Math.min(9,garageScene.inspection.distance+e.deltaY*.004));},{passive:false});
}
function upgradePrice(kind,id){return Core.UPGRADE_PRICES[kind][save.upgrades[id]?.[kind]||0];}
function field(label,content,hint=''){return `<div class="drive-field"><label>${label}${hint?'<small>'+hint+'</small>':''}</label><div class="drive-row">${content}</div></div>`;}
function selectSetting(key,values){return `<select aria-label="${key}" data-setting="${key}">${values.map(([v,n])=>`<option value="${v}" ${String(settings()[key])===String(v)?'selected':''}>${n}</option>`).join('')}</select>`;}
function sliderSetting(key,min,max,step=1){return `<input aria-label="${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${settings()[key]}"><output class="drive-value">${Number(settings()[key]).toFixed(step<1?2:0)}</output>`;}
function checkSetting(key){return `<input aria-label="${key}" type="checkbox" data-setting="${key}" ${settings()[key]?'checked':''}>`;}
function openSettings(tab='main',from=state){if(tab==='graphics'){openGraphics();return;}if(state!=='settings'){settingsBack=from==='paused'?'paused':from==='wrecked'?'wrecked':'menu';setState('settings');}settingsTab=tab;let content='';
if(tab==='main')content=field('Vehicle occupants',selectSetting('vehicleOccupants',['none','driver','goch yo bih','full ah family'].map(x=>[x,x])),'Applies to your car and traffic. Two-seat cars carry only the two adults in family mode.')+field('License plate',`<input id="driveLicensePlate" aria-label="License plate" type="text" maxlength="8" value="${escapeText(settings().licensePlate)}" autocomplete="off" spellcheck="false"><button data-action="plate">Apply</button>`,'Up to 8 letters, numbers, spaces or dashes. Saved for all your cars.')+field('Speed & distance units',selectSetting('units',[['mph','mph'],['kmh','km/h']]))+field('Damage',selectSetting('damageMode',[['standard','Standard'],['cosmetic','Cosmetic']]),'Standard damage affects steering, power and brakes. Cosmetic keeps visible dents without changing handling. Applied on the next drive.')+field('First-play tips',checkSetting('tips'),'Show a quick introduction before driving.')+'<button class="drive-danger" data-action="reset">Reset platdo Drive progress</button>';
if(tab==='display')content=field('Graphics settings','<button data-action="graphics">Open Graphics</button>','Resolution, distance, lighting, shadows and performance.')+field('Field of view',`<span class="drive-fov-pair"><input aria-label="FOV slider" data-fov type="range" min="1" max="250" value="${Math.min(250,settings().fov)}"><input aria-label="FOV value" data-fov type="number" min="1" max="1000000000" value="${settings().fov}"><output id="driveFovLens">${(window.PlatdoGraphics.projectFov?.(settings().fov)||settings().fov).toFixed(1)}° lens</output></span>`,'Values above 150 widen toward a 179° perspective lens; stored values support up to 1,000,000,000.')+field('Chase distance',sliderSetting('chaseDistance',2.5,18,.1),'Metres behind the car.')+field('Chase height',sliderSetting('chaseHeight',1.5,5,.1))+field('Camera shake',sliderSetting('cameraShake',0,1,.05))+field('Speed field of view',checkSetting('speedFov'))+field('Reduced camera motion',checkSetting('reducedMotion'))+field('Show FPS',checkSetting('showFPS'))+field('Frame-rate cap',`<select aria-label="Shared frame-rate cap" id="driveFrameCap">${[30,60,120,240].map(v=>`<option ${P.frameRate===v?'selected':''}>${v}</option>`).join('')}</select>`,'Shared across PLATDO. Physics always run at 120 Hz.');
if(tab==='environment')content=field('Traffic drivers only',checkSetting('trafficDriverOnly'),'Force one male driver and no passengers in traffic cars. Your car keeps its selected occupants. The none preset empties all cars.');
if(tab==='audio')content=field('Master volume',sliderSetting('master',0,1,.05))+field('Engine',sliderSetting('engine',0,1,.05))+field('Tires',sliderSetting('tires',0,1,.05))+field('Impacts',sliderSetting('impacts',0,1,.05))+field('Traffic & environment',sliderSetting('environment',0,1,.05))+field('Menu music',sliderSetting('music',0,1,.05))+field('Mute all driving-game audio',checkSetting('mute'));
if(tab==='controls')content=controlsHTML();
if(tab==='admin'){adminPanel();return;}
if(tab==='save')content=field('Autosave interval',selectSetting('autosave',Array.from({length:10},(_,i)=>[i+1,(i+1)+' minute'+(i?'s':'')])))+`<p style="margin-top:20px">Last successful save: <b id="driveLastSave">${lastSave||'Not saved this session'}</b></p><div class="drive-row"><button class="primary" data-action="save">Save now</button><button data-action="export">Export save</button><button data-action="import">Import save</button></div><p style="font-size:12px;margin-top:18px">Export a JSON backup to move your cars, credits, records, and controls to another computer. Import replaces only platdo Drive progress.</p>`;
panels.innerHTML=`<section class="drive-panel drive-settings"><button class="quiet drive-back" data-action="settingsBack">← ${settingsBack==='paused'?'Pause menu':settingsBack==='wrecked'?'Wreck menu':'Main menu'}</button><h2>Settings</h2><nav class="drive-tabs">${['main','environment','graphics','display','audio','controls','save','admin'].map(t=>`<button class="${tab===t?'active':''}" data-action="tab" data-tab="${t}">${t}</button>`).join('')}</nav><div class="drive-panel-card">${content}</div></section>`;}
function controlsHTML(){if(mobileMode())return '<p>Mobile controls are active. Change PC / Mobile in the game selector’s Main Settings.</p><div class="drive-field"><label>Steering</label><span>Move the left stick left or right.</span></div><div class="drive-field"><label>Pedals</label><span>Hold Gas or Brake. Keep braking after stopping to reverse. The stick also controls forward and reverse.</span></div><div class="drive-field"><label>Drifting</label><span>Hold Drift (the handbrake) while steering.</span></div><div class="drive-field"><label>Looking</label><span>Drag the Look area to look around while driving.</span></div><div class="drive-field"><label>Other actions</label><span>Camera, Recover, Horn, and Pause are on-screen buttons.</span></div>';return '<p>Chase: right-drag to orbit and scroll to zoom; the camera follows again after you stop. Hood and Cockpit: move the mouse to look. Changing cameras recenters the view.</p>'+Object.entries(bindingNames).map(([id,label])=>field(label,`<button class="drive-binding" data-action="bind" data-bind="${id}">${escapeText(keyName(save.bindings[id]))}</button>`,id==='pause'?'Escape always pauses.':id==='throttle'?'Arrow keys also drive when not assigned to another action.':'')).join('')+'<p style="font-size:12px;margin-top:15px">Select a key to remap it. Assigning a key already in use swaps the two actions. Press Escape to cancel.</p><button data-action="defaults">Restore default controls</button>';}
function controls(){setState('controls');panels.innerHTML=`<section class="drive-panel drive-settings"><button class="quiet drive-back" data-action="menu">← Main menu</button><h2>Make yourself at home.</h2><div class="drive-panel-card">${controlsHTML()}</div></section>`;}
function askConfirm(title,text,callback){clearInput();const modal=$('.drive-confirm');modal.hidden=false;modal.innerHTML=`<div class="drive-panel-card"><h2>${title}</h2><p>${text}</p><div class="drive-row"><button id="driveConfirmCancel">Cancel</button><button id="driveConfirmOK" class="primary">Confirm</button></div></div>`;$('#driveConfirmCancel').onclick=()=>{modal.hidden=true;};$('#driveConfirmOK').onclick=()=>{modal.hidden=true;callback();};$('#driveConfirmCancel').focus();}
function resetProgress(){askConfirm('Reset this garage?','This permanently clears platdo Drive cars, credits, records, upgrades, and controls. Other PLATDO games and shared display settings stay unchanged.',()=>{try{for(const key of[SAVE,'pre-upgrade-save-backup','unreadable-save-backup'])storage.remove(key);wreckMenu=false;Object.assign(admin,{unlocked:false,invincible:false,invincibleRailGuards:false,speed:null,acceleration:1,traction:1,steering:1,brakes:1});clearCreditStreak();save=Core.createDefaultSave();density=save.settings.trafficDensity||'medium';lastSave='';scene=null;createScene();writeSave();openSettings('main');toast('platdo Drive progress reset.');updateBalance();}catch(_){toast('Reset failed because browser storage is unavailable.');}});}
function exportSave(){const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PlatdoDrive-Save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported. Keep this JSON file with your game.');}
function applyImport(data){let candidate;try{candidate=Core.validateSave(data,true);}catch(e){toast('Import rejected: '+e.message);return false;}askConfirm('Import this save?','Replace this game’s progress with '+candidate.credits.toLocaleString()+' credits and '+candidate.owned.length+' owned car(s)? Other games will not change.',()=>{try{storage.set(SAVE,JSON.stringify(candidate));wreckMenu=false;save=candidate;density=save.settings.trafficDensity||'medium';scene=null;createScene();lastSave=new Date().toLocaleTimeString();openSettings('save');updateBalance();toast('Save imported.');}catch(_){toast('Import was not applied: browser storage is unavailable.');}});return true;}
$('#driveImport').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>1048576){toast('Import rejected: save files must be smaller than 1 MB.');return;}try{applyImport(JSON.parse(await file.text()));}catch(_){toast('Import rejected: this is not a valid JSON save.');}};
root.addEventListener('pointerdown',()=>{firstGesture=true;audio.unlock();},{passive:true});
root.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const a=button.dataset.action;audio.click();
switch(a){case'navigation':openNavigation();break;case'mapBack':closeNavigation();break;case'markLocation':markLocation();break;case'quickTravel':travelToSelection();break;case'clearWaypoint':sim.waypoint=null;persistNavigation();renderNavigation();break;case'mapLocation':selectNavigationPoint(Number(button.dataset.fraction));break;case'admin':openAdmin();break;case'adminUnlock':unlockAdmin();break;case'adminBack':leaveAdmin();break;case'adminReset':Object.assign(admin,{invincible:false,invincibleRailGuards:false,speed:null,acceleration:1,traction:1,steering:1,brakes:1});applyAdmin();adminPanel();break;case'adminMoney':grantAdminMoney();break;case'plate':{const e=$('#driveLicensePlate');settings().licensePlate=e.value.toUpperCase().replace(/[^A-Z0-9 -]/g,'').trim().slice(0,8)||'PLATDO';e.value=settings().licensePlate;syncSettings();writeSave();toast('License plate applied.');break;}case'wreckBack':showWreckMenu(false);break;case'menu':menu();break;case'modes':modeMenu();break;case'map':selectMap(button.dataset.map);break;case'records':records();break;case'repair':sim.recovery();resume();notice('Repaired and back on the road');break;case'rotateCar':finishGarageGesture();garageScene.inspection.yaw+=Number(button.dataset.direction)*.4;break;case'elevateCar':finishGarageGesture();garageScene.inspection.elevation=Math.max(.8,Math.min(6,garageScene.inspection.elevation+Number(button.dataset.direction)*.5));break;case'zoomCar':finishGarageGesture();garageScene.inspection.distance=Math.max(3.7,Math.min(9,garageScene.inspection.distance+Number(button.dataset.direction)*.6));break;case'begin':begin(button.dataset.mode);break;case'ready':ready();break;case'pause':pause();break;case'resume':resume();break;case'restart':begin(mode);break;case'garage':garage();break;case'garageBack':returnFromGarage();break;case'car':garage(button.dataset.car);break;case'carStep':{const ids=Object.keys(Core.CARS);garage(ids[(ids.indexOf(garageCar)+Number(button.dataset.direction)+ids.length)%ids.length]);break;}case'garageTab':finishGarageGesture();garageTab=button.dataset.tab;garageTool='inspect';garage(garageCar);break;case'previewCar':previewGarageCar(button.dataset.previewCar);break;case'previewSmoke':previewGarageSmoke(button.dataset.previewSmoke);break;case'equipSmoke':{const result=Core.purchaseSmoke(save,garageSmokeOption,garageCar);if(result.ok){writeSave();audio.confirm();garage(garageCar);}else toast(result.reason);break;}case'previewPart':previewGaragePart(button.dataset.previewPart);break;case'partCategory':garageCategory=button.dataset.category;garageOption=null;garagePreviewOption=null;refreshGarageTools();break;case'paintTool':finishGarageGesture();garageTool=button.dataset.tool;refreshGarageTools();$('.drive-preview-hint').textContent=garageTool==='paint'?'PAINT · draw directly on the body':'INSPECT · drag the car to rotate';break;case'equipPart':{const result=Core.purchasePart(save,garageCategory,garageOption,garageCar);if(result.ok){writeSave();audio.confirm();garage(garageCar);}else toast(result.reason||'More credits needed.');break;}case'factoryPart':{const result=Core.equipPart(save,garageCategory,null,garageCar);if(result.ok){writeSave();garage(garageCar);}break;}case'undoPaint':finishGarageGesture();Core.undoPaint(save,garageCar);writeSave();garageScene.setPaint(configFor(garageCar).paint);refreshGarageTools();break;case'clearPaint':finishGarageGesture();Core.clearPaint(save,garageCar);writeSave();garageScene.setPaint(configFor(garageCar).paint);refreshGarageTools();break;case'retryGraphics':scene=null;if(createScene())menu();break;case'graphics':openGraphics();break;case'settings':openSettings();break;case'tab':openSettings(button.dataset.tab);break;case'settingsBack':if(settingsBack==='wrecked'){showWreckMenu(false);}else if(settingsBack==='paused'){state=pausedState;pause();}else menu();break;case'controls':controls();break;case'hub':if(window.PlatdoDriveStandalone)menu();else location.hash='';break;
case'purchase':{if(save.owned.includes(garageCar)){save.selected=garageCar;writeSave();garage(garageCar);}else{const result=Core.purchaseCar(save,garageCar);if(result.ok){save.selected=garageCar;writeSave();audio.confirm();garage(garageCar);}else toast(result.reason||'More credits needed. Free Drive earns 50 CR per '+formatShortDistance(100)+'; finishing challenges also pays CR.');}break;}
case'upgrade':{const result=Core.buyUpgrade(save,button.dataset.upgrade,garageCar);if(result.ok){writeSave();audio.confirm();garage(garageCar);}else toast(result.reason||'More credits needed.');break;}
case'paint':finishGarageGesture();Core.setPaintColor(save,button.dataset.paint,garageCar);writeSave();garageScene.setPaint(configFor(garageCar).paint);refreshGarageTools();break;
case'bind':binding=button.dataset.bind;root.querySelectorAll('.drive-binding').forEach(b=>b.classList.remove('listening'));button.classList.add('listening');button.innerHTML='Press any key<span class="platdo-bind-wait" aria-hidden="true"></span>';button.setAttribute('aria-label','Press any key…');keys.clear();break;
case'defaults':save.bindings={...Core.DEFAULT_BINDINGS};writeSave();state==='controls'?controls():openSettings('controls');break;
case'save':if(writeSave(true)&&$('#driveLastSave'))$('#driveLastSave').textContent=lastSave;break;case'export':exportSave();break;case'import':$('#driveImport').click();break;case'reset':resetProgress();break;}
});
// Hover/focus only changes the independent preview; explicit buy/equip owns persistence.
root.addEventListener('pointerover',event=>{if(event.pointerType==='touch'||mobileMode()||state!=='garage'||garageGesture)return;const button=event.target.closest('[data-preview-car],[data-preview-part],[data-preview-smoke]');if(!button||button.contains(event.relatedTarget))return;clearTimeout(garageHoverTimer);garageHoverTimer=setTimeout(()=>{garageHoverTimer=null;if(state!=='garage'||garageGesture||!button.isConnected||!button.matches(':hover'))return;if(button.dataset.previewCar)previewGarageCar(button.dataset.previewCar);else if(button.dataset.previewSmoke)previewGarageSmoke(button.dataset.previewSmoke);else previewGaragePart(button.dataset.previewPart);},150);});
root.addEventListener('pointerout',event=>{const button=event.target.closest('[data-preview-car],[data-preview-part],[data-preview-smoke]');if(button&&!button.contains(event.relatedTarget)){clearTimeout(garageHoverTimer);garageHoverTimer=null;}});
root.addEventListener('focusin',event=>{if(state!=='garage')return;const button=event.target.closest('[data-preview-car],[data-preview-part],[data-preview-smoke]');if(button?.dataset.previewCar)previewGarageCar(button.dataset.previewCar);else if(button?.dataset.previewPart)previewGaragePart(button.dataset.previewPart);else if(button?.dataset.previewSmoke)previewGarageSmoke(button.dataset.previewSmoke);});
root.addEventListener('input',e=>{if(e.target.hasAttribute('data-fov')){if(e.target.value==='')return;settings().fov=window.PlatdoGraphics.sanitizeFov(Number(e.target.value));for(const peer of root.querySelectorAll('[data-fov]'))if(peer!==e.target)peer.value=peer.type==='range'?Math.min(250,settings().fov):settings().fov;$('#driveFovLens').textContent=window.PlatdoGraphics.projectFov(settings().fov).toFixed(1)+'° lens';syncSettings();writeSave();return;}if(e.target.id==='driveBrushColor'){brushColor=e.target.value;return;}if(e.target.id==='driveBrushSize'){brushSize=Number(e.target.value);e.target.nextElementSibling.textContent=Math.round(brushSize*1000);return;}if(e.target.id==='driveBaseColor'){finishGarageGesture();Core.setPaintColor(save,e.target.value,garageCar);garageScene.setPaint(configFor(garageCar).paint);writeSave();return;}if(e.target.dataset.admin){updateAdminControl(e.target);return;}const key=e.target.dataset.setting;if(!key)return;const old=settings()[key];settings()[key]=e.target.type==='checkbox'?e.target.checked:typeof old==='number'?Number(e.target.value):e.target.value;if(e.target.nextElementSibling?.tagName==='OUTPUT')e.target.nextElementSibling.textContent=Number(e.target.value).toFixed(Number(e.target.step)<1?2:0);syncSettings();});
root.addEventListener('change',e=>{if(e.target.id==='driveGarageCar'){garage(e.target.value);return;}if(e.target.id==='drivePartOption'){previewGaragePart(e.target.value);return;}if(e.target.id==='driveBaseColor'){refreshGarageTools();return;}if(e.target.dataset.setting){writeSave();if(e.target.dataset.setting==='graphics')openSettings('display');}if(e.target.id==='driveDensity'){density=e.target.value;save.settings.trafficDensity=density;settings().trafficCount=null;writeSave();}if(e.target.id==='driveFrameCap'){try{P.setFrameRate(Number(e.target.value));}catch(_){toast('The frame cap changed, but shared settings could not be saved.');}}});
function getInput(){if(!['playing','countdown'].includes(state))return{throttle:0,brake:0,steer:0,handbrake:false};if(mobileMode())return{throttle:Math.max(mobileInput.throttle?1:0,mobileInput.y),brake:Math.max(mobileInput.brake?1:0,-mobileInput.y),steer:-mobileInput.x,handbrake:mobileInput.handbrake};const held=action=>keys.has(save.bindings[action])||Object.entries(arrowActions).some(([key,a])=>a===action&&keys.has(key)&&!Object.values(save.bindings).includes(key));return{throttle:held('throttle')?1:0,brake:held('brake')?1:0,steer:(held('left')?1:0)+(held('right')?-1:0),handbrake:held('handbrake')};}
function onKey(e){if(!active||state==='error'||mobileMode())return;if(e.target.closest('input,select,textarea,[contenteditable="true"]')&&e.code!=='Escape'){if(e.code==='Enter'&&e.target.id==='driveAdminCode'){e.preventDefault();unlockAdmin();}return;}if(!$('.drive-confirm').hidden){if(e.code==='Escape')$('.drive-confirm').hidden=true;return;}if(binding){e.preventDefault();e.stopImmediatePropagation();if(e.repeat)return;const b=binding;binding=null;if(e.code!=='Escape'){if(!/^(Key[A-Z]|Digit[0-9]|Arrow(Up|Down|Left|Right)|Space|ShiftLeft|ShiftRight|Enter|Backspace|BracketLeft|BracketRight|Semicolon|Quote|Comma|Period|Slash|Backslash|Minus|Equal|Backquote)$/.test(e.code)){toast('Choose a letter, number, arrow, or space key.');}else{const prior=save.bindings[b],conflict=Object.keys(save.bindings).find(k=>k!==b&&save.bindings[k]===e.code);if(conflict)save.bindings[conflict]=prior;save.bindings[b]=e.code;writeSave();}}state==='controls'?controls():openSettings('controls');return;}
const recognized=Object.values(save.bindings).includes(e.code)||Object.keys(arrowActions).includes(e.code)||e.code==='Escape';if(!recognized)return;e.preventDefault();e.stopImmediatePropagation();audio.unlock();
if(!e.repeat&&(e.code==='Escape'||e.code===save.bindings.pause)){if(e.code==='Escape'&&performance.now()<ignoreUnlockEscapeUntil){ignoreUnlockEscapeUntil=0;return;}if(['playing','countdown'].includes(state))pause();else if(state==='paused')resume();else if(state==='admin'&&adminBack==='paused')leaveAdmin();else if(state==='settings'&&settingsBack==='paused'){state=pausedState;pause();}else if(state==='navigation')closeNavigation();else if(state==='garage'&&garageBack==='paused')returnFromGarage();else if(e.code==='Escape'&&!window.PlatdoDriveStandalone)location.hash='';else menu();return;}
if(state==='navigation'&&e.code===save.bindings.map){if(!e.repeat)closeNavigation();return;}if(!['playing','countdown'].includes(state))return;keys.add(e.code);if(e.repeat)return;if(e.code===save.bindings.camera)cycleCamera();if(e.code===save.bindings.recover&&state==='playing')sim.recovery();if(e.code===save.bindings.horn)audio.horn();if(e.code===save.bindings.headlights)cycleHeadlights();if(e.code===save.bindings.map)openNavigation();}
window.addEventListener('keydown',onKey,true);window.addEventListener('keyup',e=>{keys.delete(e.code);if(active&&['playing','countdown'].includes(state)&&(['Space',...Object.values(save.bindings),...Object.keys(arrowActions)].includes(e.code))){e.preventDefault();e.stopImmediatePropagation();}},true);
function focusLost(){releaseDrivePointer();finishGarageGesture();clearInput();if(active)pause();}
window.addEventListener('blur',focusLost);document.addEventListener('visibilitychange',()=>{if(document.hidden){focusLost();stopLoop();}else if(active)startLoop();});
canvas.addEventListener('webglcontextlost',()=>{if(active){pause();clearInput();toast('Graphics paused. Open Graphics to lower settings while the browser restores the display.');}});window.addEventListener('resize',resize);window.addEventListener('platdo:settingschange',resize);
window.addEventListener('platdo:controlsmodechange',()=>{releaseDrivePointer();finishGarageGesture();clearInput();root.classList.toggle('drive-mobile',mobileMode());if(active&&state==='controls')controls();else if(active&&state==='settings'&&settingsTab==='controls')openSettings('controls');if(active&&['playing','countdown'].includes(state))renderHUD();});
window.addEventListener('platdo:save',()=>{finishGarageGesture();writeSave();});window.addEventListener('pagehide',()=>{finishGarageGesture();writeSave();});
window.addEventListener('platdo:beforereset',()=>{saving=false;clearCreditStreak();clearInterval(saveTimer);clearInput();if(active){pause();setVisible(false);}audio.update(sim?.player||{},{},'hidden',0);});
function persistNavigation(){if(!sim||!route)return;save.navigation??={};save.navigation[route.mapId]={waypoint:sim.waypoint,recoveryPoint:sim.recoveryPoint};writeSave();}
function restoreNavigation(){const nav=save.navigation?.[route.mapId];if(nav?.waypoint)sim.setWaypoint(nav.waypoint.x,nav.waypoint.z,nav.waypoint.label);if(nav?.recoveryPoint)sim.setRecoveryPoint(nav.recoveryPoint.x,nav.recoveryPoint.z,nav.recoveryPoint.label);}
function openNavigation(){if(!sim||!sessionStarted)return;if(state==='navigation'){closeNavigation();return;}mapBack=state==='paused'?'paused':['playing','countdown'].includes(state)?state:'playing';mapSelection=sim.waypoint?{...sim.waypoint}:null;setState('navigation');renderNavigation();}
function closeNavigation(){if(mapBack==='paused'){state=pausedState;pause();}else{setState(mapBack);}}
function selectNavigationPoint(fraction){if(!sim||!Number.isFinite(fraction))return;const at=route.at(route.length*Math.max(0,Math.min(1,fraction)));mapSelection={x:at.x,z:at.z,label:(route.map.zones||[]).find(z=>fraction>=z.start&&fraction<z.end)?.name||'Road destination'};renderNavigation();}
function markLocation(){if(!mapSelection)return;sim.setWaypoint(mapSelection.x,mapSelection.z,mapSelection.label);persistNavigation();renderNavigation();notice('GPS destination marked');}
function travelToSelection(){if(!mapSelection)return false;if(!sim.quickTravel(mapSelection.x,mapSelection.z,mapSelection.label)){toast('No clear road space here. Choose another spot.');return false;}sim.setWaypoint(mapSelection.x,mapSelection.z,mapSelection.label);persistNavigation();closeNavigation();notice('Travel checkpoint saved · Recover returns here');return true;}
function mapProjection(w,h,pad=35){const points=[...route.samples,...(route.connectors||[]).flatMap(c=>c.samples)],xs=points.map(p=>p.x),zs=points.map(p=>p.z),minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs),scale=Math.min((w-pad*2)/(maxX-minX),(h-pad*2)/(maxZ-minZ)),cx=(minX+maxX)/2,cz=(minZ+maxZ)/2;return{xy:p=>[w/2+(p.x-cx)*scale,h/2+(p.z-cz)*scale],world:(x,y)=>({x:(x-w/2)/scale+cx,z:(y-h/2)/scale+cz})};}
function renderNavigation(){if(state!=='navigation')return;panels.innerHTML=`<section class="drive-panel drive-navigation"><button class="quiet drive-back" data-action="mapBack">← Return to drive</button><div class="drive-kicker">Navigation / ${escapeText(route.map.name)}</div><h2>Choose your destination</h2><p>Click or tap a road to select it. Mark it for GPS, or quick travel and set your new Recover checkpoint.</p><canvas id="driveNavigationMap" width="900" height="540" role="img" aria-label="Interactive road map. Choose a road destination or use the location buttons."></canvas><div class="drive-map-locations">${[.05,.25,.5,.75].map((f,i)=>`<button data-action="mapLocation" data-fraction="${f}">${escapeText((route.map.zones||[]).find(z=>f>=z.start&&f<z.end)?.name||'Road stop '+(i+1))}</button>`).join('')}</div><div class="drive-navigation-actions"><strong>${escapeText(mapSelection?.label||'Select a location')}</strong><button data-action="markLocation" ${mapSelection?'':'disabled'}>Mark on GPS</button><button class="primary" data-action="quickTravel" ${mapSelection?'':'disabled'}>Quick travel</button><button data-action="clearWaypoint" ${sim.waypoint?'':'disabled'}>Clear GPS</button></div>${mode==='free'?'':'<small>Quick travel makes this challenge unranked.</small>'}</section>`;const map=$('#driveNavigationMap');map.addEventListener('pointerdown',e=>{if(e.button!==0)return;const r=map.getBoundingClientRect(),p=mapProjection(map.width,map.height).world((e.clientX-r.left)*map.width/r.width,(e.clientY-r.top)*map.height/r.height),road=route.driveNearest?.(p.x,p.z)||route.nearest(p.x,p.z);mapSelection={x:road.x,z:road.z,label:'Road destination'};renderNavigation();});drawNavigationMap();}
function drawNavigationMap(){const c=$('#driveNavigationMap');if(!c||!sim)return;const ctx=c.getContext('2d'),{xy}=mapProjection(c.width,c.height);ctx.fillStyle='#0a161c';ctx.fillRect(0,0,c.width,c.height);ctx.lineJoin='round';for(const [index,path]of [route,...(route.connectors||[])].entries()){ctx.beginPath();path.samples.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});if(!index)ctx.closePath();ctx.lineWidth=index?7:12;ctx.strokeStyle=index?'#7c8f91':'#cad4cc';ctx.stroke();}drawWaypoint(ctx,xy,sim.waypoint);for(const [p,color,r]of[[sim.recoveryPoint,'#f7c562',8],[mapSelection,'#60c7ff',9],[sim.player,'#e3f788',7]])if(p){const[x,y]=xy(p);ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#071218';ctx.lineWidth=3;ctx.stroke();}}
function drawWaypoint(ctx,xy,waypoint){if(!waypoint)return;const[x,y]=xy(waypoint),[px,py]=xy(sim.player);ctx.save();ctx.setLineDash([6,5]);ctx.strokeStyle='#6ccaff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(px,py);ctx.lineTo(x,y);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fillStyle='#6ccaff';ctx.fill();ctx.restore();}
function drawMap(){if(!route||!sim)return;const c=$('.drive-map'),ctx=c.getContext('2d'),samples=route.samples;let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const p of samples){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);}const scale=Math.min(305/(maxX-minX),260/(maxZ-minZ)),cx=(minX+maxX)/2,cz=(minZ+maxZ)/2;const xy=p=>[175+(p.x-cx)*scale,155+(p.z-cz)*scale];ctx.clearRect(0,0,350,310);ctx.lineJoin='round';ctx.lineWidth=7;ctx.strokeStyle='#16313fc0';ctx.beginPath();samples.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#e5ece2';ctx.stroke();ctx.lineWidth=2;ctx.strokeStyle='#9bbcaf';for(const c of route.connectors||[]){ctx.beginPath();c.samples.forEach((p,i)=>{const[x,y]=xy(p);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}if(mode==='trial'){(sim.checkpoints||[]).forEach((s,i)=>{const[x,y]=xy(route.at(typeof s==='number'?s:s.s));ctx.beginPath();ctx.arc(x,y,i===sim.checkpointIndex?7:3,0,Math.PI*2);ctx.fillStyle=i<sim.checkpointIndex?'#748476':i===sim.checkpointIndex?'#dcf18b':'#9db1b2';ctx.fill();});}drawWaypoint(ctx,xy,sim.waypoint);const[x,y]=xy(sim.player);ctx.save();ctx.translate(x,y);ctx.rotate(-sim.player.yaw+Math.PI);ctx.beginPath();ctx.moveTo(0,-9);ctx.lineTo(6,6);ctx.lineTo(0,3);ctx.lineTo(-6,6);ctx.closePath();ctx.fillStyle='#dcf18b';ctx.fill();ctx.restore();}
function renderHUD(){if(!sim)return;const p=sim.player,speed=Math.abs(p.speed)*(settings().units==='mph'?2.236936:3.6);$('.drive-speed strong').textContent=Math.round(speed);$('.drive-unit').textContent=settings().units==='mph'?'MPH':'KM/H';$('.drive-gear').textContent=p.speed<-.4?'R':Math.abs(p.speed)<.4?'N':p.gear||1;$('.drive-rpm i').style.width=Math.min(100,Math.max(0,(p.engineRPM||0)/(sim.config.redlineRPM||7000)*100))+'%';$('.drive-camera-label').textContent=mobileMode()?camera+' CAMERA':camera+' · '+keyName(save.bindings.camera)+' CAMERA · '+keyName(save.bindings.recover)+' RECOVER';$('.drive-hud-mode').textContent=modes[mode][0];$('.drive-condition').hidden=false;$('.drive-condition i').style.width=Math.max(0,p.condition)+'%';$('.drive-condition i').style.background=p.condition<30?'#f3a185':'#d9ed83';const left=$('.drive-hud-value'),secondary=$('.drive-hud-secondary'),right=$('#driveRightValue'),label=$('#driveRightLabel');
if(mode==='rush'){left.textContent=Math.ceil(Math.max(0,sim.remaining))+'s';secondary.textContent='CONDITION '+Math.round(p.condition)+'%';right.textContent=Math.round(sim.score).toLocaleString();label.textContent=sim.multiplier.toFixed(2)+'× MULTIPLIER';}
else if(mode==='trial'){left.textContent=formatTime(sim.time+(sim.penalty||0));secondary.textContent=(sim.penalty?'+'+sim.penalty+'s PENALTY · ':'')+'CHECKPOINT '+Math.min((sim.checkpointIndex||0)+1,sim.checkpoints.length)+' / '+sim.checkpoints.length+' · '+formatShortDistance(((sim.checkpoints[sim.checkpointIndex]||route.length)-p.s+route.length)%route.length);right.textContent=formatTime(recordValue('trial'));label.textContent='BEST · THIS ROAD & SETUP';}
else{left.textContent=formatDistance(sim.distance);secondary.textContent='CONDITION '+Math.round(p.condition)+'% · +'+(sim.freeDriveCredits||0).toLocaleString()+' CR EARNED';right.textContent=save.credits.toLocaleString()+' CR';label.textContent=Math.round(sim.score).toLocaleString()+' PTS · '+formatShortDistance(100-(sim.eligibleDistance||0)%100,true).toUpperCase()+' TO +50 CR';}
if(p.oncoming)secondary.textContent+=' · ONCOMING';
$('.drive-zone').textContent=route.zone?route.zone(p.s):((p.s/route.length)<.34?'Coastal stretch':p.s/route.length<.68?'Woodland bends':'Tunnel & outskirts');drawMap();}
function processEvents(){for(const e of sim.events.splice(0)){if(e.type==='railBreak'){audio.impact(Math.min(1,e.impact/30),{...e,surface:'metal'});}else if(e.type==='explosion'){audio.explosion(Math.hypot((e.x||0)-sim.player.x,(e.z||0)-sim.player.z));}else if(e.type==='collision'){bankDrivingCredits();breakCreditStreak();audio.impact(Math.min(1,(e.impact||e.damage||10)/35),e);}else if(e.type==='pass'||e.type==='nearMiss'||e.type==='oncoming')notice(e.text||(e.type==='nearMiss'?'NEAR MISS':'CLEAN PASS')+' +'+Math.round(e.points||e.amount||100));else if(e.type==='recovery')notice(mode==='trial'?'Recovered · +5 seconds':mode==='rush'?'Recovered · −200 points · −5 seconds':'Back on the road');else if(e.type==='checkpoint'){notice('CHECKPOINT '+(sim.checkpointIndex||1));audio.confirm();}}}
function stopLoop(){if(rafId!==null){cancelAnimationFrame(rafId);rafId=null;}accumulator=0;}
function startLoop(){if(!active||document.hidden||rafId!==null)return;lastFrame=performance.now();lastRender=0;accumulator=0;rafId=requestAnimationFrame(frame);}
